class BarcodeOperations:
    """/v1/barcode operations."""

    def __init__(self, core: Core) -> None:
        self._core = core

    def decode(
        self,
        *,
        file: FileInput,
        callback_url: Optional[str] = None,
        pages: Optional[str] = None,
        symbologies: Optional[list[Literal["code128", "code39", "ean13", "ean8", "upca", "itf14", "itf", "datamatrix", "pdf417", "qr"]]] = None,
        mode: Optional[Literal["sync", "async"]] = None,
        idempotency_key: Optional[str] = None,
        accept: Optional[str] = None,
        request_id: Optional[str] = None,
        timeout: Optional[float] = None,
    ) -> Answer[BarcodeDecodeResult]:
        """Decode barcodes. Answers 200 inline, or 202 with a job above its sync limit (or with mode async). Meter api_codes; scope api.barcode.decode.execute."""
        params = {"file": file, "callback_url": callback_url, "pages": pages, "symbologies": symbologies}
        return self._core.operation("/v1/barcode/decode", params, input_kind="file", extra=[], mode=mode, idempotency_key=idempotency_key, accept=accept, request_id=request_id, timeout=timeout)

    def generate(
        self,
        *,
        content: str,
        symbology: Literal["code128", "code39", "ean13", "ean8", "upca", "itf14", "datamatrix", "pdf417"],
        callback_url: Optional[str] = None,
        colors: Optional[Colors] = None,
        format: Optional[Literal["png", "svg", "pdf"]] = None,
        height: Optional[int] = None,
        human_readable: Optional[bool] = None,
        margin: Optional[int] = None,
        width: Optional[int] = None,
        mode: Optional[Literal["sync", "async"]] = None,
        idempotency_key: Optional[str] = None,
        accept: Optional[str] = None,
        request_id: Optional[str] = None,
        timeout: Optional[float] = None,
    ) -> Answer[BarcodeGenerateResult]:
        """Generate a 1D or 2D barcode. Answers 200 inline, or 202 with a job above its sync limit (or with mode async). Meter api_codes; scope api.barcode.generate.execute."""
        params = {"content": content, "symbology": symbology, "callback_url": callback_url, "colors": colors, "format": format, "height": height, "human_readable": human_readable, "margin": margin, "width": width}
        return self._core.operation("/v1/barcode/generate", params, input_kind="none", extra=[], mode=mode, idempotency_key=idempotency_key, accept=accept, request_id=request_id, timeout=timeout)


