class WebhooksResource:
    """Webhook endpoints and deliveries."""

    def __init__(self, core: Core) -> None:
        self._core = core

    def create(self, *, events: list[str], url: str, description: Optional[str] = None, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> WebhookEndpoint:
        """Register an endpoint; the signing secret is returned only here."""
        return self._core.call("POST", f"/v1/webhooks", query=None, json=_drop_none({"description": description, "events": events, "url": url}), idempotency_key=idempotency_key, request_id=request_id)

    def delete(self, id: str, *, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> Deleted:
        """Delete an endpoint."""
        return self._core.call("DELETE", f"/v1/webhooks/{_seg(id)}", query=None, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def get(self, id: str, *, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> WebhookEndpoint:
        """Read an endpoint (never the secret)."""
        return self._core.call("GET", f"/v1/webhooks/{_seg(id)}", query=None, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def get_delivery(self, id: str, delivery_id: str, *, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> WebhookDeliveryDetail:
        """A delivery with the request it sent (headers, signature redacted, payload)."""
        return self._core.call("GET", f"/v1/webhooks/{_seg(id)}/deliveries/{_seg(delivery_id)}", query=None, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def list(self, *, cursor: Optional[str] = None, limit: Optional[int] = None, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> WebhooksListData:
        """List endpoints."""
        return self._core.call("GET", f"/v1/webhooks", query={"limit": limit, "cursor": cursor}, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def list_all(self, *, limit: Optional[int] = None, request_id: Optional[str] = None) -> Iterator[WebhookEndpoint]:
        """Every item of list, page after page (follows next_cursor)."""
        return self._core.paginate(f"/v1/webhooks", {"limit": limit}, request_id=request_id)

    def list_deliveries(self, id: str, *, cursor: Optional[str] = None, event_type: Optional[str] = None, limit: Optional[int] = None, status: Optional[Literal["pending", "delivering", "delivered", "failed", "dead_lettered"]] = None, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> WebhooksListDeliveriesData:
        """List deliveries, newest first (status=failed includes dead-lettered)."""
        return self._core.call("GET", f"/v1/webhooks/{_seg(id)}/deliveries", query={"status": status, "event_type": event_type, "limit": limit, "cursor": cursor}, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def list_deliveries_all(self, id: str, *, status: Optional[Literal["pending", "delivering", "delivered", "failed", "dead_lettered"]] = None, event_type: Optional[str] = None, limit: Optional[int] = None, request_id: Optional[str] = None) -> Iterator[WebhookDelivery]:
        """Every item of list_deliveries, page after page (follows next_cursor)."""
        return self._core.paginate(f"/v1/webhooks/{_seg(id)}/deliveries", {"status": status, "event_type": event_type, "limit": limit}, request_id=request_id)

    def ping(self, id: str, *, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> WebhookPing:
        """Send a ping event."""
        return self._core.call("POST", f"/v1/webhooks/{_seg(id)}/ping", query=None, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def retry_delivery(self, id: str, delivery_id: str, *, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> WebhookDelivery:
        """Replay a delivery now."""
        return self._core.call("POST", f"/v1/webhooks/{_seg(id)}/deliveries/{_seg(delivery_id)}/retry", query=None, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def roll_callback_secret(self, *, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> CallbackSecret:
        """Roll the callback_url signing secret (returned once)."""
        return self._core.call("POST", f"/v1/webhooks/callback-secret", query=None, json=None, idempotency_key=idempotency_key, request_id=request_id)

    def update(self, id: str, *, description: Optional[str] = None, events: Optional[list[str]] = None, status: Optional[Literal["active", "disabled"]] = None, url: Optional[str] = None, idempotency_key: Optional[str] = None, request_id: Optional[str] = None) -> WebhookEndpoint:
        """Change url, events, description or status (active re-enables)."""
        return self._core.call("PATCH", f"/v1/webhooks/{_seg(id)}", query=None, json=_drop_none({"description": description, "events": events, "status": status, "url": url}), idempotency_key=idempotency_key, request_id=request_id)


def _seg(value: str) -> str:
    from urllib.parse import quote

    return quote(value, safe="")


def _drop_none(d: Dict[str, Any]) -> Dict[str, Any]:
    return {k: v for k, v in d.items() if v is not None}


class GeneratedClient:
    """Every operation and resource of the Lowco API."""

    def __init__(self, core: Core) -> None:
        self._core = core
        self.barcode = BarcodeOperations(core)
        """/v1/barcode operations."""
        self.docai = DocaiOperations(core)
        """/v1/docai operations."""
        self.ocr = OcrOperations(core)
        """/v1/ocr operations."""
        self.pdf = PdfOperations(core)
        """/v1/pdf operations."""
        self.qr = QrOperations(core)
        """/v1/qr operations."""
        self.render = RenderOperations(core)
        """/v1/render operations."""
        self.audit = AuditResource(core)
        """Console audit log."""
        self.files = FilesResource(core)
        """Uploaded and produced files."""
        self.jobs = JobsResource(core)
        """Asynchronous jobs."""
        self.keys = KeysResource(core)
        """."""
        self.requests = RequestsResource(core)
        """."""
        self.settings = SettingsResource(core)
        """Environment settings."""
        self.templates = TemplatesResource(core)
        """Stored render templates."""
        self.usage = UsageResource(core)
        """Usage and balance."""
        self.webhooks = WebhooksResource(core)
        """Webhook endpoints and deliveries."""
